import {mountNoiseParticles} from './noise-particles.js?v=20261006-lake-surface1';
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
function elasticType(element,{sound=false}={}){
 const label=element.getAttribute('aria-label')||element.textContent.replace(/\s+/g,' ').trim();element.setAttribute('aria-label',label);
 const custom=element.hasAttribute('data-art-custom');
 const walker=document.createTreeWalker(element,NodeFilter.SHOW_TEXT),nodes=[];while(!custom&&walker.nextNode())nodes.push(walker.currentNode);
 for(const node of nodes){const part=document.createDocumentFragment();for(const ch of node.textContent){if(ch===' '){part.append(document.createTextNode(' '));continue}const s=document.createElement('span');s.className='elastic-letter';s.setAttribute('aria-hidden','true');s.textContent=ch;part.append(s)}node.replaceWith(part)}
 const letters=[...element.querySelectorAll(custom?'.noise-letter':'.elastic-letter')].map(el=>({el,x:0,y:0,vx:0,vy:0,tx:0,ty:0,rot:0}));let active=false,last=0,raf=0,pointer=null,rects=[],lastBrush=-1,lastBrushAt=0;const voices=['kick','snare','hat','tom','rim'];let hitIndex=0;
 function reset(){pointer=null;letters.forEach(l=>{l.tx=l.ty=0});element.classList.remove('type-touched')}
 function move(e){if(sound&&e.pointerType!=='touch'){const now=performance.now(),near=letters.map((l,i)=>({i,r:l.el.getBoundingClientRect()})).filter(l=>l.r.width&&l.r.height).map(l=>({...l,d:Math.hypot(l.r.x+l.r.width/2-e.clientX,l.r.y+l.r.height/2-e.clientY)})).sort((a,b)=>a.d-b.d)[0];if(near&&near.d<200&&near.i!==lastBrush&&now-lastBrushAt>180){lastBrush=near.i;lastBrushAt=now;playHit(voices[near.i%voices.length],{gesture:false,x:(e.clientX-innerWidth/2)/innerWidth})}}if(reduced)return;pointer={x:e.clientX,y:e.clientY};rects=letters.map(l=>l.el.getBoundingClientRect());element.classList.add('type-touched');active=true;start();letters.forEach((l,i)=>{const r=rects[i],dx=r.x+r.width/2-l.x-pointer.x,dy=r.y+r.height/2-l.y-pointer.y,d=Math.hypot(dx,dy),force=Math.max(0,1-d/(sound?200:140));l.tx=dx/(d||1)*force*(sound?24:11);l.ty=dy/(d||1)*force*(sound?28:14);l.el.style.setProperty('--letter-heat',force.toFixed(2))})}
 element.addEventListener('pointermove',move);element.addEventListener('pointerleave',()=>{lastBrush=-1;reset();letters.forEach(l=>l.el.style.setProperty('--letter-heat','0'))});
 function start(){if(!raf&&!reduced&&!document.hidden)raf=requestAnimationFrame(frame)}
 function frame(now){raf=0;const dt=Math.min(.03,(now-last)/1000||.016);last=now;if(!active||document.hidden||reduced)return;let energy=0;letters.forEach((l,i)=>{l.vx+=(l.tx-l.x)*115*dt;l.vy+=(l.ty-l.y)*115*dt;l.vx*=Math.exp(-10*dt);l.vy*=Math.exp(-10*dt);l.x+=l.vx*dt;l.y+=l.vy*dt;energy+=Math.abs(l.x)+Math.abs(l.y);l.el.style.transform=`translate(${l.x.toFixed(2)}px,${l.y.toFixed(2)}px) rotate(${(l.vx*.035).toFixed(2)}deg)`});if(!pointer&&energy<.05)active=false;if(active)start()}
 document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else if(active)start()});
 if(sound){element.tabIndex=0;element.setAttribute('role','button');element.setAttribute('aria-label','Make some noise — play a short percussion hit');const hit=e=>{active=true;start();letters.forEach((l,i)=>{l.vy=-85-Math.random()*80;l.vx=(Math.random()-.5)*90;l.tx=l.ty=0});element.classList.remove('noise-hit');void element.offsetWidth;element.classList.add('noise-hit');playHit(voices[hitIndex++%voices.length],{gesture:true,x:e.clientX?(e.clientX-innerWidth/2)/innerWidth:0});};element.addEventListener('click',hit);element.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();hit(e)}})}
}
async function playHit(voice,options){const title=document.querySelector('#noise-title'),water=document.documentElement.lang.startsWith('zh');title.dataset.audioState='starting';const index=['kick','snare','hat','tom','rim'].indexOf(voice),played=water?await window.lotusSfx?.playWater({value:(index+.5)/5,...options}):await window.lotusSfx?.playPercussion(voice,options);title.dataset.audioState=played?'played':'idle';if(played)title.dataset.noiseVoice=water?'water-synth':voice}
for(const heading of document.querySelectorAll('#about-title, #studio-title'))elasticType(heading);
elasticType(document.querySelector('.contact h2'),{sound:true});
const particleTitle=document.querySelector('#noise-title');
particleTitle.addEventListener('lotus-noise-brush',e=>playHit(e.detail.voice,{gesture:false,x:e.detail.x,value:e.detail.value,motion:e.detail.motion}));
let noiseTask;
function prepareNoise(){return noiseTask??=mountNoiseParticles(particleTitle).catch(()=>{particleTitle.dataset.particleRenderer='fallback';particleTitle.querySelector('.noise-particle-type').replaceWith(Object.assign(document.createElement('span'),{className:'noise-poster-zh noise-particle-fallback',textContent:'造声'}))})}
const noiseObserver=new IntersectionObserver(entries=>{if(entries.some(e=>e.isIntersecting)){prepareNoise();noiseObserver.disconnect()}},{rootMargin:'200px'});noiseObserver.observe(particleTitle);
for(const button of document.querySelectorAll('.bio-token')){button.addEventListener('pointerenter',()=>{document.querySelector('.instinct-caption').textContent=button.dataset.line;document.querySelector('#portrait-wrap')?.dispatchEvent(new Event('lotus-artist-smile'))});button.addEventListener('focus',()=>{document.querySelector('.instinct-caption').textContent=button.dataset.line});}
const note=document.createElement('p');note.className='noise-invitation mono';note.textContent='BRUSH THE LETTERS. TAP TO MAKE A BEAT.';document.querySelector('.contact h2').after(note);

function localizeNoiseLabel(){const zh=document.documentElement.lang.startsWith('zh'),el=document.querySelector('#noise-title');if(el)el.setAttribute('aria-label',zh?'来点造声 — 轻触，让声音流动':'Make some noise — play a short percussion hit');note.textContent=zh?'轻触字面，泛起一圈水波。':'BRUSH THE LETTERS. TAP TO MAKE A BEAT.'}
window.addEventListener('lotus-language-change',localizeNoiseLabel);localizeNoiseLabel();
